import { Request, Response } from 'express';
import { AddTaskUseCase } from '../application/AddTaskUseCase';
import { AssignTaskUseCase } from '../application/AssignTaskUseCase';
import { ListTasksUseCase, ListTasksFilter } from '../application/ListTasksUseCase';
import { MarkTaskDoneUseCase } from '../application/MarkTaskDoneUseCase';
import { TaskDTO } from '../application/TaskDTO';
import { Task } from '../domain/Task';

export class TaskController {
  constructor(
    private addTaskUseCase: AddTaskUseCase,
    private assignTaskUseCase: AssignTaskUseCase,
    private listTasksUseCase: ListTasksUseCase,
    private markTaskDoneUseCase: MarkTaskDoneUseCase,
  ) {}

  add(req: Request, res: Response): void {
    const { id, projectId, title, description, dueDate } = req.body;

    if (!id || !projectId || !title || !description) {
      res
        .status(400)
        .json({ error: 'Missing required fields: id, projectId, title, description' });
      return;
    }

    const parsedDueDate = dueDate ? new Date(dueDate) : null;
    const task = this.addTaskUseCase.execute(
      id,
      projectId,
      title,
      description,
      parsedDueDate,
    );

    res.status(201).json(this.taskToDTO(task));
  }

  assign(req: Request, res: Response): void {
    const { taskId, assigneeId } = req.body;

    if (!taskId || !assigneeId) {
      res.status(400).json({ error: 'Missing required fields: taskId, assigneeId' });
      return;
    }

    try {
      const task = this.assignTaskUseCase.execute(taskId, assigneeId);
      res.json(this.taskToDTO(task));
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Unknown error';
      res.status(400).json({ error: message });
    }
  }

  list(req: Request, res: Response): void {
    const projectId = req.params.projectId;
    const { status, assigneeId } = req.query;

    if (!projectId || Array.isArray(projectId)) {
      res.status(400).json({ error: 'Missing required parameter: projectId' });
      return;
    }

    const filter: ListTasksFilter = {};
    if (status && typeof status === 'string') {
      filter.status = status as 'todo' | 'in_progress' | 'done';
    }
    if (assigneeId && typeof assigneeId === 'string') {
      filter.assigneeId = assigneeId;
    }

    const tasks = this.listTasksUseCase.execute(projectId, filter);
    res.json(tasks.map((t) => this.taskToDTO(t)));
  }

  markDone(req: Request, res: Response): void {
    const { taskId } = req.body;

    if (!taskId) {
      res.status(400).json({ error: 'Missing required field: taskId' });
      return;
    }

    try {
      const task = this.markTaskDoneUseCase.execute(taskId);
      res.json(this.taskToDTO(task));
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Unknown error';
      res.status(400).json({ error: message });
    }
  }

  private taskToDTO(task: Task): TaskDTO {
    return {
      id: task.id,
      projectId: task.projectId,
      title: task.title,
      description: task.description,
      dueDate: task.dueDate?.toISOString() ?? null,
      status: task.status,
      assigneeId: task.assigneeId,
    };
  }
}

